"""The country-specific part of the legal notice: for each country in the list, what its law says about copying
and translating for yourself and about what may be possessed, in English and in the country's own languages.

The sections are summaries written for readers, not legal advice; the sources are in docs/LEGAL_SOURCES.md.
A country not in the list gets ``OTHER_TEXTS`` in the window's language.
"""

from __future__ import annotations

from dataclasses import dataclass, field

OTHER = "other"


@dataclass(frozen=True)
class Jurisdiction:
    code: str  # ISO 3166-1 alpha-2, upper case
    name: str  # in English
    native: str  # in its own language ("" when that is English)
    languages: tuple[str, ...]  # window languages spoken there, the first is the default
    sections: dict[str, str] = field(default_factory=dict)  # window language -> the country's part ("en" always)

    def label(self) -> str:
        return f"{self.name} ({self.native})" if self.native and self.native != self.name else self.name


JURISDICTIONS: dict[str, Jurisdiction] = {}


def _add(code: str, name: str, native: str, languages: tuple[str, ...], **sections: str) -> None:
    assert "en" in sections, code
    JURISDICTIONS[code] = Jurisdiction(code, name, native, languages, {k.replace("_", "-"): v for k, v in sections.items()})


_add("JP", "Japan", "日本", ("ja", "en"), en="""Japan. Copyright: Article 30(1) of the Copyright Act lets you copy a work for personal or family use, and Article 47-6 lets you translate it for that use; showing or passing the copy or the translation to anyone else is an infringement (Article 49). The exception does not cover copies made by circumventing a protection measure (Article 30(1)(ii)); TASlation captures what the viewer has already drawn and circumvents nothing; the capture stays in memory and is at most an incidental reproduction in computer processing, which Article 47-4 allows. Your store's terms may still forbid it. Content: possessing sexual images of real children has been a crime since the 2014 amendment of the Child Pornography Act; drawings are outside that Act. Obscenity under Article 175 of the Penal Code is an offence of distribution and of possession for sale, not of private possession, so a manga sold in Japan is lawful to own here. A country you take your reader to may see all of this differently.""",
     ja="""日本。著作権: 著作権法第30条第1項により個人的または家庭内での使用のための複製が、第47条の6によりその目的での翻訳が認められています。訳文や翻訳したページを他人に見せたり、投稿・共有したりすれば侵害になります（第49条）。技術的保護手段を回避して作った複製は例外の対象外ですが（第30条第1項第2号）、TASlation はビューアが描画済みの画面を取り込むだけで、何も回避しません。取り込んだ画面はメモリ上にとどまり、複製にあたるとしても第47条の4が認める電子計算機の処理に付随する一時的な複製です。電子書店の利用規約が画面の取り込みを禁じている場合はあります。内容: 実在の児童を写した性的な画像の所持は、児童ポルノ禁止法（2014年改正）により犯罪です。絵による描写はこの法律の対象外です。刑法第175条のわいせつ物の罪は頒布や販売目的の所持を罰するもので、自分で見るためだけの所持は罰せられません。日本で販売されている漫画を日本で持つことは適法ですが、ビューアごと持ち出した先の国では、ここに書いたすべてが違う扱いになることがあります。""")

_add("GB", "United Kingdom", "", ("en",), en="""United Kingdom. Copyright: there is no private-copying exception. The one introduced in 2014 (section 28B of the Copyright, Designs and Patents Act) was quashed by the High Court in 2015, and a translation made for yourself is an adaptation that no exception covers; fair dealing is for research, private study, criticism and the like, not for reading for pleasure. The translation made for yourself therefore infringes in law (the capture itself is a transient copy of the kind the temporary-copies exception covers), but as a civil matter: there is no criminal offence without commercial dealing or distribution, and no private, unshared use has ever been pursued. Content: possessing a "prohibited image of a child" is a criminal offence under section 62 of the Coroners and Justice Act 2009, written to reach drawn and animated images, with up to three years' imprisonment. Keep nothing you are not sure about.""")

_add("US", "United States", "", ("en",), en="""United States. Copyright: there is no private-use exception; a personal, non-commercial translation that only you see would be judged under fair use, which no court has decided for this situation. Whether capturing a screen your reader has lawfully displayed "circumvents" a protection measure under section 1201 of the DMCA is argued both ways and unsettled; TASlation reads the screen only. Infringement is a civil matter unless it is wilful and for profit or at scale. Content: 18 U.S.C. § 1466A makes possessing obscene drawings, cartoons or paintings of minors in sexual conduct a federal crime; a collector of Japanese manga pleaded guilty under it in 2009 and his books were forfeited. State obscenity laws apply as well.""")

_add("CA", "Canada", "", ("en", "fr"), en="""Canada. Copyright: section 29.22 of the Copyright Act lets you reproduce, for private purposes, a work you own a lawful copy of, as long as no digital lock is circumvented and the copy is not given away; it covers reproduction only, so a translation made for yourself is not within it and infringes in law, as a civil matter with no damage to claim when nothing is shared. Content: section 163.1 of the Criminal Code defines child pornography as any visual representation, and the Supreme Court held in R. v. Sharpe that "person" includes imaginary persons, so drawn material is covered; possession carries a minimum prison sentence. Border officers examine devices and have charged a traveller over manga on a laptop. Carry nothing you are not sure about.""",
     fr="""Canada. Droit d'auteur : l'article 29.22 de la Loi sur le droit d'auteur vous permet de reproduire, à des fins privées, une œuvre dont vous possédez un exemplaire légitime, à condition de ne contourner aucune mesure technique de protection et de ne pas donner la copie ; il ne vise que la reproduction, de sorte qu'une traduction faite pour vous-même n'en relève pas et constitue en droit une contrefaçon, de nature civile, sans préjudice indemnisable tant que rien n'est partagé. Contenu : l'article 163.1 du Code criminel définit la pornographie juvénile comme toute représentation visuelle, et la Cour suprême a jugé dans R. c. Sharpe que « personne » inclut les personnes imaginaires : le matériel dessiné est donc visé, et la possession entraîne une peine minimale d'emprisonnement. Les agents frontaliers examinent les appareils et ont déjà accusé un voyageur pour des mangas sur son ordinateur portable. N'emportez rien dont vous n'êtes pas sûr.""")

_add("AU", "Australia", "", ("en",), en="""Australia. Copyright: section 43C of the Copyright Act lets you copy a book you own into another format, once, for private use; there is no general private-use exception, and a translation made for yourself is an adaptation that no exception covers, so it infringes in law as a civil matter. Content: the Commonwealth Criminal Code and the state laws on child abuse material reach drawn and animated material, since McEwen v Simmons (NSW, 2008) held that a cartoon character can be a "person"; possession is a serious crime. Titles refused classification cannot be sold or imported, in some states possessing them is an offence, and border officers may examine the devices you travel with. Keep nothing you are not sure about.""")

_add("NZ", "New Zealand", "", ("en",), en="""New Zealand. Copyright: there is no general private-use exception; the format-shifting exception covers sound recordings only, and a translation made for yourself is not covered, so it infringes in law as a civil matter. Content: under the Films, Videos, and Publications Classification Act a publication can be "objectionable", drawings and manga included, and knowingly possessing an objectionable publication is a crime with up to ten years' imprisonment; Prosecutions over hentai manga have been brought. Keep nothing you are not sure about.""")

_add("IE", "Ireland", "", ("en",), en="""Ireland. Copyright: there is no private-copying exception; fair dealing for research or private study is the nearest provision, and it is not for reading for pleasure, so a translation made for yourself infringes in law as a civil matter. Content: the Child Trafficking and Pornography Act 1998 defines child pornography as any visual representation of a person who is or appears to be a child, drawn figures expressly included where the predominant impression is that of a child; knowing possession is a crime with up to five years' imprisonment. Keep nothing you are not sure about.""")

_add("DE", "Germany", "Deutschland", ("de", "en"), en="""Germany. Copyright: § 53 UrhG lets a natural person make copies for private use from a source that is not obviously unlawful, and § 23 lets an adaptation such as a translation be made freely; only publishing or exploiting it needs the author's consent. Reading with TASlation for yourself is therefore on firm ground, as long as no technical protection is circumvented (§ 95a), which TASlation does not do. Content: § 184b StGB criminalises possessing depictions of the sexual abuse of children that reproduce an actual or realistic ("wirklichkeitsnahes") event; clearly fictional drawings are generally outside it, realistic ones are not, and §§ 184c and 184 cover youths and other pornography.""",
     de="""Deutschland. Urheberrecht: § 53 UrhG erlaubt natürlichen Personen Vervielfältigungen zum privaten Gebrauch von einer nicht offensichtlich rechtswidrigen Vorlage, und nach § 23 darf eine Bearbeitung wie eine Übersetzung frei hergestellt werden; erst die Veröffentlichung oder Verwertung bedarf der Zustimmung des Urhebers. Das Lesen mit TASlation für sich selbst steht damit auf festem Boden, solange keine technische Schutzmaßnahme umgangen wird (§ 95a), was TASlation nicht tut. Inhalt: § 184b StGB stellt den Besitz von Darstellungen sexuellen Kindesmissbrauchs unter Strafe, die ein tatsächliches oder wirklichkeitsnahes Geschehen wiedergeben; eindeutig fiktive Zeichnungen fallen in der Regel nicht darunter, wirklichkeitsnahe schon, und die §§ 184c und 184 erfassen Jugendpornografie und sonstige Pornografie.""")

_add("AT", "Austria", "Österreich", ("de", "en"), en="""Austria. Copyright: § 42 UrhG lets a natural person make copies of a work for private use; making a translation for yourself is not expressly covered, but Austrian law, like German law, requires the author's consent for exploiting an adaptation rather than for making it. Content: § 207a StGB criminalises possessing sexual depictions of minors, and since its wording reaches "realistic" ("wirklichkeitsnahe") depictions, realistic drawings are covered while clearly fictional ones generally are not.""",
     de="""Österreich. Urheberrecht: § 42 UrhG erlaubt natürlichen Personen Vervielfältigungen eines Werks zum privaten Gebrauch; das Anfertigen einer Übersetzung für sich selbst ist nicht ausdrücklich erfasst, doch verlangt das österreichische Recht wie das deutsche die Zustimmung des Urhebers für die Verwertung einer Bearbeitung, nicht für ihre Herstellung. Inhalt: § 207a StGB stellt den Besitz sexualbezogener Darstellungen Minderjähriger unter Strafe; da der Wortlaut auch „wirklichkeitsnahe“ Darstellungen erfasst, fallen wirklichkeitsnahe Zeichnungen darunter, eindeutig fiktive in der Regel nicht.""")

_add("CH", "Switzerland", "Schweiz / Suisse / Svizzera", ("de", "fr", "it", "en"), en="""Switzerland. Copyright: Article 19 of the Copyright Act allows any use of a published work in the private sphere, which includes translating it for yourself, as long as no technical protection is circumvented. Content: Article 197 of the Criminal Code counts depictions of sexual acts with minors that never took place, drawn and animated ones included, as hard pornography, and possessing them for your own consumption is punishable unless the work has a cultural or scientific value worth protecting. Keep nothing you are not sure about.""",
     de="""Schweiz. Urheberrecht: Art. 19 URG erlaubt jede Verwendung eines veröffentlichten Werks im persönlichen Bereich, also auch eine Übersetzung für sich selbst, solange keine technische Schutzmassnahme umgangen wird. Inhalt: Art. 197 StGB zählt Darstellungen nicht tatsächlicher sexueller Handlungen mit Minderjährigen, gezeichnete und animierte eingeschlossen, zur harten Pornografie, und ihr Besitz zum eigenen Konsum ist strafbar, sofern das Werk keinen schutzwürdigen kulturellen oder wissenschaftlichen Wert hat. Behalten Sie nichts, dessen Sie sich nicht sicher sind.""",
     fr="""Suisse. Droit d'auteur : l'article 19 de la LDA autorise toute utilisation d'une œuvre divulguée dans le cercle privé, y compris sa traduction pour soi-même, tant qu'aucune mesure technique de protection n'est contournée. Contenu : l'article 197 du Code pénal range dans la pornographie dure les représentations d'actes sexuels non effectifs avec des mineurs, dessins et animations compris, et leur possession pour sa propre consommation est punissable, sauf valeur culturelle ou scientifique digne de protection. Ne gardez rien dont vous n'êtes pas sûr.""",
     it="""Svizzera. Diritto d'autore: l'articolo 19 della LDA consente qualsiasi utilizzazione di un'opera pubblicata nell'ambito privato, compresa la traduzione per sé, purché non si eluda alcuna misura tecnica di protezione. Contenuto: l'articolo 197 del Codice penale considera pornografia dura le rappresentazioni di atti sessuali non effettivi con minorenni, disegni e animazioni compresi, e il loro possesso per il proprio consumo è punibile, salvo un valore culturale o scientifico degno di protezione. Non conservare nulla di cui non sei sicuro.""")

_add("FR", "France", "", ("fr", "en"), en="""France. Copyright: Article L122-5 of the Intellectual Property Code allows private copies from a lawful source, but Article L122-4 makes any translation without the author's consent unlawful, even one nobody sees; that is a civil matter with no damage to claim as long as nothing is shared. Content: Article 227-23 of the Penal Code criminalises possessing pornographic images or "representations" of minors, and the government has stated that a drawing is a representation; since 2013 it also covers images of persons whose physical appearance is that of a minor. Prosecutions over manga are rare, but the text allows them.""",
     fr="""France. Droit d'auteur : l'article L122-5 du Code de la propriété intellectuelle autorise la copie privée à partir d'une source licite, mais l'article L122-4 rend illicite toute traduction faite sans le consentement de l'auteur, même si personne ne la voit ; c'est une question civile, sans préjudice indemnisable tant que rien n'est partagé. Contenu : l'article 227-23 du Code pénal réprime la détention d'images ou de « représentations » pornographiques de mineurs, et le gouvernement a précisé qu'un dessin est une représentation ; depuis 2013 il vise aussi les images de personnes dont l'aspect physique est celui d'un mineur. Les poursuites visant des mangas sont rares, mais le texte les permet.""")

_add("BE", "Belgium", "België / Belgique", ("nl", "fr", "en"), en="""Belgium. Copyright: the Code of Economic Law allows a private copy within the family circle (Article XI.190); whether that covers a translation made for yourself is not settled, so treat one as tolerated rather than permitted, and never share it. Content: the Criminal Code (Article 417/13, formerly 383bis) criminalises knowingly possessing material that visually depicts a minor, or a person who appears to be one, in sexual conduct, real or simulated; the police have stated that manga can fall under it even though no real minor is involved. Keep nothing you are not sure about.""",
     nl="""België. Auteursrecht: het Wetboek van economisch recht staat een privékopie in familiekring toe (artikel XI.190); of dat ook een vertaling voor eigen gebruik dekt, is niet uitgemaakt, dus beschouw die eerder als gedoogd dan als toegelaten, en deel ze nooit. Inhoud: het Strafwetboek (artikel 417/13, vroeger 383bis) stelt het wetens bezitten strafbaar van materiaal dat een minderjarige, of iemand die er een lijkt, visueel in seksueel gedrag toont, echt of gesimuleerd; de politie heeft gesteld dat manga eronder kan vallen, ook al is er geen echte minderjarige bij betrokken. Bewaar niets waarvan u niet zeker bent.""",
     fr="""Belgique. Droit d'auteur : le Code de droit économique autorise la copie privée dans le cercle de famille (article XI.190) ; que cela couvre une traduction faite pour soi-même n'est pas tranché, aussi faut-il la considérer comme tolérée plutôt que permise, et ne jamais la partager. Contenu : le Code pénal (article 417/13, anciennement 383bis) réprime la possession, en connaissance de cause, de matériel représentant visuellement un mineur, ou une personne qui paraît l'être, dans un comportement sexuel, réel ou simulé ; la police a précisé que des mangas peuvent en relever même sans mineur réel. Ne gardez rien dont vous n'êtes pas sûr.""")

_add("NL", "Netherlands", "Nederland", ("nl", "en"), en="""Netherlands. Copyright: Article 16b of the Copyright Act allows a copy for your own practice, study or use from a lawful source, and since the Act counts a translation as a reproduction (Article 13), a translation made for yourself is covered as well. Content: the Criminal Code (Article 240b, moved to Article 252) criminalises possessing virtual child pornography when it is realistic; drawings and animations are outside it unless they can hardly be told from images of a real child, and the courts have not drawn that line consistently. Keep nothing you are not sure about.""",
     nl="""Nederland. Auteursrecht: artikel 16b Auteurswet staat een kopie voor eigen oefening, studie of gebruik toe uit een legale bron, en omdat de wet een vertaling als verveelvoudiging aanmerkt (artikel 13), valt ook een vertaling voor eigen gebruik eronder. Inhoud: het Wetboek van Strafrecht (artikel 240b, verplaatst naar artikel 252) stelt het bezit van virtuele kinderpornografie strafbaar wanneer die realistisch is; tekeningen en animaties vallen erbuiten, tenzij ze nauwelijks van beelden van een echt kind te onderscheiden zijn, en de rechtspraak heeft die grens niet consequent getrokken. Bewaar niets waarvan u niet zeker bent.""")

_add("ES", "Spain", "España", ("es", "en"), en="""Spain. Copyright: Article 31.2 of the Intellectual Property Act allows a private copy from a lawful source (paid for by the levy), but transformation, which includes translation (Article 21), has no private-use exception, so a translation made for yourself infringes in law as a civil matter. Content: Article 189 of the Penal Code criminalises possessing child pornography, defined to include "realistic images" of a minor; the Prosecution Service's Circular 2/2015 states that cartoons and manga are not realistic images and fall outside it, while realistic drawings and images of persons who appear to be minors remain covered.""",
     es="""España. Derechos de autor: el artículo 31.2 de la Ley de Propiedad Intelectual permite la copia privada a partir de una fuente lícita (compensada con el canon), pero la transformación, que incluye la traducción (artículo 21), no tiene excepción de uso privado, de modo que una traducción hecha para uno mismo constituye en derecho una infracción, de carácter civil. Contenido: el artículo 189 del Código Penal castiga la posesión de pornografía infantil, definida de forma que incluye las «imágenes realistas» de un menor; la Circular 2/2015 de la Fiscalía señala que los dibujos animados y el manga no son imágenes realistas y quedan fuera, mientras que los dibujos realistas y las imágenes de personas que parezcan menores siguen comprendidos.""")

_add("MX", "Mexico", "México", ("es", "en"), en="""Mexico. Copyright: Article 148(IV) of the Federal Copyright Act allows one copy of a work for the personal and private use of the person making it, without profit; translation is not covered, so one made for yourself is an infringement in law, a civil matter when nothing is shared. Content: Article 202 of the Federal Penal Code criminalises possessing child pornography; it is written around real persons under eighteen, and drawn material is not clearly within it.""",
     es="""México. Derechos de autor: el artículo 148, fracción IV, de la Ley Federal del Derecho de Autor permite una sola copia de una obra para uso personal y privado de quien la hace, sin fines de lucro; la traducción no está comprendida, así que la hecha para uno mismo constituye en derecho una infracción, de carácter civil mientras no se comparta nada. Contenido: el artículo 202 del Código Penal Federal castiga la posesión de pornografía infantil; está redactado en torno a personas reales menores de dieciocho años, y el material dibujado no queda claramente comprendido.""")

_add("AR", "Argentina", "", ("es", "en"), en="""Argentina. Copyright: Law 11.723 has no private-copying exception, so even a translation for yourself infringes in law; it is a civil matter as long as nothing is shared. Content: Article 128 of the Penal Code, as amended in 2018, punishes the mere possession of sexual "representations" of persons under eighteen; whether a drawing is such a representation is disputed among jurists and no court has settled it, so treat drawn material as a risk.""",
     es="""Argentina. Derechos de autor: la Ley 11.723 no tiene excepción de copia privada, así que incluso una traducción para uno mismo constituye en derecho una infracción; es una cuestión civil mientras no se comparta nada. Contenido: el artículo 128 del Código Penal, reformado en 2018, castiga la mera posesión de «representaciones» sexuales de menores de dieciocho años; si un dibujo es una representación de ese tipo se discute entre los juristas y ningún tribunal lo ha resuelto, así que trata el material dibujado como un riesgo.""")

_add("BR", "Brazil", "Brasil", ("pt", "en"), en="""Brazil. Copyright: Law 9.610 allows only the reproduction of small excerpts for the copier's private use (Article 46 II); a translation made for yourself is an infringement in law, a civil matter when nothing is shared. Content: the Child and Adolescent Statute (Articles 241-B and 241-C) criminalises possessing sexual scenes involving children or adolescents, including ones simulated by altering or assembling "any other form of visual representation", which jurists read to include drawings; the courts have not settled the point for manga.""",
     pt="""Brasil. Direitos autorais: a Lei 9.610 permite apenas a reprodução de pequenos trechos para uso privado do copista (art. 46, II); uma tradução feita para si mesmo é, em direito, uma violação, de natureza civil enquanto nada for compartilhado. Conteúdo: o Estatuto da Criança e do Adolescente (arts. 241-B e 241-C) criminaliza a posse de cenas de sexo envolvendo criança ou adolescente, inclusive as simuladas por adulteração ou montagem de "qualquer outra forma de representação visual", expressão que os juristas entendem abranger desenhos; os tribunais não firmaram entendimento sobre os mangás.""")

_add("PT", "Portugal", "", ("pt", "en"), en="""Portugal. Copyright: Article 75(2)(a) of the Code of Copyright allows reproduction for private use (paid for by the levy); translation is a separate right with no private-use exception, so one made for yourself infringes in law as a civil matter. Content: Article 176 of the Penal Code criminalises possessing pornographic material with a "realistic representation" of a minor; stylised drawings are generally outside it, realistic ones are not, and the line is debated.""",
     pt="""Portugal. Direitos de autor: o artigo 75.º, n.º 2, alínea a), do Código do Direito de Autor permite a reprodução para uso privado (compensada pela taxa); a tradução é um direito autónomo sem exceção de uso privado, pelo que uma tradução feita para si próprio é, em direito, uma violação, de natureza civil. Conteúdo: o artigo 176.º do Código Penal criminaliza a posse de material pornográfico com "representação realista" de menor; os desenhos estilizados ficam em geral de fora, os realistas não, e a fronteira é discutida.""")

_add("IT", "Italy", "Italia", ("it", "en"), en="""Italy. Copyright: the private-copying exception (Article 71-sexies of Law 633/1941) covers sound and video recordings only, and translation is an exclusive right with no private-use exception, so a translation made for yourself infringes in law as a civil matter. Content: Article 600-quater.1 of the Penal Code extends the possession offence to "virtual" images that make unreal situations appear true; drawings were long read as outside it, but the Court of Cassation extended the notion in 2025 to images produced by graphic processing with no link to real situations, and a collector of comics has been prosecuted. Keep nothing you are not sure about.""",
     it="""Italia. Diritto d'autore: l'eccezione per copia privata (art. 71-sexies della legge 633/1941) riguarda solo fonogrammi e videogrammi, e la traduzione è un diritto esclusivo senza eccezione per uso privato, quindi una traduzione fatta per sé viola la legge, come questione civile. Contenuto: l'art. 600-quater.1 del codice penale estende il reato di detenzione alle immagini "virtuali" che fanno apparire vere situazioni non reali; i disegni sono stati a lungo considerati esclusi, ma la Cassazione nel 2025 ha esteso la nozione alle immagini ottenute con elaborazione grafica senza legame con situazioni reali, e un collezionista di fumetti è stato processato. Non conservare nulla di cui non sei sicuro.""")

_add("PL", "Poland", "Polska", ("pl", "en"), en="""Poland. Copyright: Article 23 of the Copyright Act allows the personal use of a published work, and that permission is broad; a translation kept to yourself is generally read as within it, while sharing it is not. Content: Article 202 § 4b of the Penal Code criminalises possessing pornographic content with a "generated or processed image" of a minor; whether a drawing is such an image is debated, and realistic ones are the more likely to be.""",
     pl="""Polska. Prawo autorskie: art. 23 ustawy o prawie autorskim pozwala korzystać z rozpowszechnionego utworu w zakresie własnego użytku osobistego, a zakres ten jest szeroki; tłumaczenie zachowane dla siebie zwykle uznaje się za mieszczące się w nim, a jego udostępnianie już nie. Treści: art. 202 § 4b kodeksu karnego penalizuje posiadanie treści pornograficznych przedstawiających „wytworzony albo przetworzony wizerunek” małoletniego; to, czy rysunek jest takim wizerunkiem, jest sporne, a rysunki realistyczne z większym prawdopodobieństwem zostaną za taki wizerunek uznane.""")

_add("RU", "Russia", "Россия", ("ru", "en"), en="""Russia. Copyright: Article 1273 of the Civil Code allows reproduction for personal purposes; translation is a separate right with no personal-use exception, so a translation made for yourself is not expressly permitted, a civil matter when nothing is shared. Content: Article 242.1 of the Criminal Code punishes making, storing and moving pornographic depictions of minors only with the purpose of distribution, so private storage alone is not that offence, and whether drawn or animated depictions count is not settled; Article 242 covers other pornography when distributed.""",
     ru="""Россия. Авторское право: статья 1273 ГК разрешает воспроизведение в личных целях; перевод — отдельное право без исключения для личного использования, так что перевод для себя прямо не разрешён; пока ничего не передаётся другим, это гражданско-правовой вопрос. Содержание: статья 242.1 УК наказывает изготовление, хранение и перемещение порнографических изображений несовершеннолетних только в целях распространения, так что одно лишь хранение для себя не образует состава этого преступления, а подпадают ли под неё рисованные и анимационные изображения, не решено; статья 242 касается иной порнографии при её распространении.""")

_add("TR", "Türkiye", "", ("tr", "en"), en="""Türkiye. Copyright: Article 38 of the Law on Intellectual and Artistic Works allows reproducing a work for personal use without commercial purpose; translation is a separate right with no personal-use exception, so a translation made for yourself is not expressly permitted, a civil matter when nothing is shared. Content: Article 226(3) of the Penal Code punishes possessing or storing obscene images that use children, or persons who look like children, and practitioners read it to reach drawn and animated depictions; possession carries two to five years' imprisonment. Obscene material with adults only is not an offence to possess privately.""",
     tr="""Türkiye. Telif hakkı: Fikir ve Sanat Eserleri Kanunu'nun 38. maddesi, bir eserin kâr amacı gütmeden kişisel kullanım için çoğaltılmasına izin verir; çeviri, kişisel kullanım istisnası olmayan ayrı bir haktır, bu yüzden kendiniz için yaptığınız bir çeviriye ilişkin açık bir izin yoktur; hiçbir şey paylaşılmadığı sürece bu bir özel hukuk meselesidir. İçerik: Türk Ceza Kanunu'nun 226. maddesinin 3. fıkrası, çocukları ya da çocuk gibi görünen kişileri kullanan müstehcen görüntüleri bulundurmayı veya depolamayı cezalandırır ve hukuk uygulayıcıları bu hükmü çizim ve animasyon tasvirlerini de kapsayacak biçimde yorumlar; bulundurmanın cezası iki yıldan beş yıla kadar hapistir. Yalnızca yetişkinleri içeren müstehcen materyali özel olarak bulundurmak suç değildir.""")

_add("ID", "Indonesia", "", ("id", "en"), en="""Indonesia. Copyright: Article 46 of the Copyright Law allows one copy of a published work for personal use; translation is not covered, so one made for yourself is not expressly permitted, a civil matter when nothing is shared. Content: the Pornography Law (44/2008) defines pornography to include cartoons and animation and bans possessing it, but its explanatory note excludes possession for oneself and one's own interest; distribution, including online under the ITE Law, is a crime. Keep nothing you are not sure about, and share nothing.""",
     id="""Indonesia. Hak cipta: Pasal 46 Undang-Undang Hak Cipta mengizinkan satu salinan dari ciptaan yang telah diumumkan untuk kepentingan pribadi; penerjemahan tidak termasuk, sehingga terjemahan untuk diri sendiri tidak secara tegas diizinkan, dan selama tidak ada yang dibagikan ini adalah urusan perdata. Konten: Undang-Undang Pornografi (44/2008) mendefinisikan pornografi sehingga mencakup kartun dan animasi, serta melarang memilikinya, tetapi penjelasannya mengecualikan kepemilikan untuk diri sendiri dan kepentingan sendiri; penyebaran, termasuk secara daring menurut UU ITE, adalah tindak pidana. Jangan simpan apa pun yang Anda ragukan, dan jangan bagikan apa pun.""")

_add("VN", "Vietnam", "Việt Nam", ("vi", "en"), en="""Vietnam. Copyright: Article 25 of the Intellectual Property Law allows making one copy for your own scientific research or study, not for reading for pleasure, and translation is not covered; a translation made for yourself is not expressly permitted, a civil matter when nothing is shared. Content: Article 326 of the Penal Code punishes making, copying, transporting or storing "depraved" material for the purpose of dissemination, with the amount of material setting the sentence; storage for yourself alone is not that offence, but administrative penalties exist for it, and what counts as depraved is decided by the authorities. Share nothing.""",
     vi="""Việt Nam. Bản quyền: Điều 25 Luật Sở hữu trí tuệ cho phép tự sao chép một bản để nghiên cứu khoa học hoặc học tập của cá nhân, không phải để đọc giải trí, và không bao gồm việc dịch; bản dịch làm cho riêng mình không được cho phép rõ ràng, và chừng nào không chia sẻ gì thì đây là vấn đề dân sự. Nội dung: Điều 326 Bộ luật Hình sự trừng phạt việc làm ra, sao chép, vận chuyển hoặc tàng trữ văn hóa phẩm đồi trụy nhằm phổ biến, với mức án tùy theo số lượng; chỉ tàng trữ cho riêng mình không phải là tội này, nhưng có thể bị xử phạt hành chính, và thế nào là đồi trụy do cơ quan chức năng quyết định. Đừng chia sẻ bất cứ thứ gì.""")

_add("CN", "China", "中国", ("zh", "en"), en="""China. Copyright: Article 24(1) of the Copyright Law allows using a published work for personal study, research or appreciation, which is read to include translating it for yourself. Content: the Criminal Law (Articles 363 to 367) punishes producing, selling or disseminating obscene materials, comics included, and the Public Security Administration Punishments Law punishes dissemination; mere private possession is not an offence, but anything you share or post is.""",
     zh="""中国。著作权：《著作权法》第二十四条第一项允许为个人学习、研究或者欣赏使用已经发表的作品，通常理解为包括为自己翻译。内容：《刑法》第三百六十三条至第三百六十七条处罚制作、贩卖、传播淫秽物品的行为，漫画也在其列，《治安管理处罚法》处罚传播行为；仅仅私下持有不构成违法，但您分享或发布任何内容都构成违法。""")

_add("TW", "Taiwan", "臺灣", ("zh-tw", "en"), en="""Taiwan. Copyright: Article 51 of the Copyright Act allows reproduction for personal or family use without profit, and Article 63 allows translating a work for that use. Content: the Child and Youth Sexual Exploitation Prevention Act criminalises possessing sexual images of children and youths, including computer-made ones that look real; whether purely drawn or animated material is covered is debated and not settled by the courts.""",
     zh_tw="""臺灣。著作權：《著作權法》第51條允許為個人或家庭非營利目的而重製，第63條允許為此目的翻譯著作。內容：《兒童及少年性剝削防制條例》對持有兒童或少年性影像的行為處以刑罰，包括以電腦合成而看似真實者；純粹繪製或動畫的作品是否包含在內仍有爭論，法院尚未定論。""")

_add("HK", "Hong Kong", "香港", ("zh-tw", "en"), en="""Hong Kong. Copyright: there is no private-copying exception; fair dealing for research or private study is the nearest provision, and a translation made for yourself is an adaptation that no exception covers, so it infringes in law as a civil matter. Content: the Prevention of Child Pornography Ordinance (Cap. 579) criminalises possessing a visual depiction of a person who is, or is depicted as being, under sixteen in a sexual way, drawings included, with a defence of artistic merit; the Control of Obscene and Indecent Articles Ordinance covers other material.""",
     zh_tw="""香港。版權：沒有私人複製的豁免；為研究或私人研習的公平處理是最接近的規定，而為自己所作的翻譯屬於改編，不在任何豁免之內，因此在法律上構成侵權，屬民事問題。內容：《防止兒童色情物品條例》（第579章）將管有以色情方式描繪未滿十六歲者或被描繪為未滿十六歲者的視像描劃定為罪行，繪畫包括在內，並設有藝術價值的免責辯護；其他物品受《淫褻及不雅物品管制條例》規管。""")

_add("SG", "Singapore", "", ("en", "zh"), en="""Singapore. Copyright: the Copyright Act 2021 has no private-copying exception for books; a translation made for yourself would be judged under its fair-use provision, which no court has applied to this situation, so it may infringe in law as a civil matter. Content: the Penal Code (section 377BK) makes possessing child abuse material an offence punishable with up to five years' imprisonment, and the material includes drawn depictions of a person who appears to a reasonable observer to be under sixteen; the Undesirable Publications Act and the Films Act make obscene publications and films offences even in private possession. Keep nothing you are not sure about.""",
     zh="""新加坡。版权：《2021年版权法》对书籍没有私人复制的例外；为自己所作的翻译将按其合理使用条款判断，而尚无法院将该条款适用于这种情形，因此在法律上可能构成侵权，属民事事宜。内容：《刑法典》第377BK条规定持有儿童性虐待材料为罪行，最高可处五年监禁，这类材料包括描绘在合理观察者看来未满十六岁者的绘画；《不良出版物法》和《电影法》规定淫秽出版物和影片即使私人持有也构成罪行。请勿保留任何您不确定的内容。""")

_add("PH", "Philippines", "", ("en",), en="""Philippines. Copyright: Section 187 of the Intellectual Property Code allows a single private copy for research and private study, not for reading for pleasure, and translation is not covered; a translation made for yourself is not expressly permitted, a civil matter when nothing is shared. Content: Republic Act 11930 (2022, replacing the Anti-Child Pornography Act) defines a "child" to include computer-generated, digitally or manually crafted images made to appear to be a child, and makes possession an offence; possessing three or more items is presumed to be for distribution. Keep nothing you are not sure about.""")

_add("KR", "South Korea", "대한민국", ("ko", "en"), en="""South Korea. Copyright: Article 30 of the Copyright Act allows reproduction for private use, and Article 36 allows translating a work for that use. Content: the Act on the Protection of Children and Youth against Sex Offenses treats sexual depictions of persons or expressions that can clearly be recognised as children or youths, animation and manga included, as child or youth sexual exploitation material, and purchasing, possessing or viewing it is a crime; a 2025 amendment removed the need to prove that you knew.""",
     ko="""대한민국. 저작권: 저작권법 제30조는 사적 이용을 위한 복제를 허용하고, 제36조는 그 이용을 위한 번역을 허용합니다. 내용: 아동·청소년의 성보호에 관한 법률은 아동·청소년으로 명백하게 인식될 수 있는 사람이나 표현물의 성적 묘사를 애니메이션과 만화를 포함하여 아동·청소년성착취물로 보며, 이를 구입·소지·시청하는 것은 범죄입니다. 2025년 개정으로 알고 있었음을 입증할 필요도 없어졌습니다.""")


