def sorted_jurisdictions() -> list[Jurisdiction]:
    """The countries by English name."""
    return sorted(JURISDICTIONS.values(), key=lambda j: j.name)


def _merge_translations() -> None:
    """The country parts written in other window languages (``jurisdiction_texts``), for the codes they cover;
    a country's own languages, written here, are kept."""
    from . import jurisdiction_texts

    for lang, texts in jurisdiction_texts.load().items():
        for code, text in texts.items():
            j = JURISDICTIONS.get(code)
            if j is not None and text.strip():
                j.sections.setdefault(lang, text)


_merge_translations()


def section(country: str | None, lang: str) -> str:
    """The country's part of the notice in *lang*; in English, under a note in *lang*, when it is not written in
    *lang*; the "not in the list" text for an unknown country."""
    j = JURISDICTIONS.get((country or "").upper())
    if j is None:
        return OTHER_TEXTS.get(lang, OTHER_TEXTS["en"])
    text = j.sections.get(lang)
    if text:
        return text
    note = FALLBACK_NOTE.get(lang, "")
    return (note + "\n\n" if note else "") + j.sections["en"]


def default_language(country: str | None) -> str | None:
    """The window language a country suggests (None for an unknown country)."""
    j = JURISDICTIONS.get((country or "").upper())
    return j.languages[0] if j else None


